import org.junit.jupiter.api.Test;
import java.util.List;
import static java.util.Arrays.asList;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatExceptionOfType;

public class TempEdgeCaseTest {

    @Test
    public void singleCoin() {
        assertThat(new ChangeCalculator(asList(1, 5, 10, 25, 100)).computeMostEfficientChange(25))
                .containsExactly(25);
    }

    @Test
    public void multipleCoins() {
        assertThat(new ChangeCalculator(asList(1, 5, 10, 25, 100)).computeMostEfficientChange(15))
                .containsExactly(5, 10);
        assertThat(new ChangeCalculator(asList(1, 5, 10, 25, 100)).computeMostEfficientChange(40))
                .containsExactly(5, 10, 25);
    }

    @Test
    public void lilliputian() {
        assertThat(new ChangeCalculator(asList(1, 4, 15, 20, 50)).computeMostEfficientChange(23))
                .containsExactly(4, 4, 15);
    }

    @Test
    public void lowerElbonian() {
        assertThat(new ChangeCalculator(asList(1, 5, 10, 21, 25)).computeMostEfficientChange(63))
                .containsExactly(21, 21, 21);
    }

    @Test
    public void largeAmount() {
        assertThat(new ChangeCalculator(asList(1, 2, 5, 10, 20, 50, 100)).computeMostEfficientChange(999))
                .containsExactly(2, 2, 5, 20, 20, 50, 100, 100, 100, 100, 100, 100, 100, 100, 100);
    }

    @Test
    public void noUnitCoin() {
        assertThat(new ChangeCalculator(asList(2, 5, 10, 20, 50)).computeMostEfficientChange(21))
                .containsExactly(2, 2, 2, 5, 10);
        assertThat(new ChangeCalculator(asList(4, 5)).computeMostEfficientChange(27))
                .containsExactly(4, 4, 4, 5, 5, 5);
    }

    @Test
    public void greedyNotOptimal() {
        assertThat(new ChangeCalculator(asList(1, 10, 11)).computeMostEfficientChange(20))
                .containsExactly(10, 10);
        assertThat(new ChangeCalculator(asList(1, 3, 4)).computeMostEfficientChange(6))
                .containsExactly(3, 3);
    }

    @Test
    public void zeroChange() {
        assertThat(new ChangeCalculator(asList(1, 5, 10, 21, 25)).computeMostEfficientChange(0)).isEmpty();
    }

    @Test
    public void unrepresentable() {
        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> new ChangeCalculator(asList(5, 10)).computeMostEfficientChange(3))
                .withMessage("The total 3 cannot be represented in the given currency.");
        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> new ChangeCalculator(asList(5, 10)).computeMostEfficientChange(94))
                .withMessage("The total 94 cannot be represented in the given currency.");
    }

    @Test
    public void negativeRejected() {
        assertThatExceptionOfType(IllegalArgumentException.class)
                .isThrownBy(() -> new ChangeCalculator(asList(1, 2, 5)).computeMostEfficientChange(-5))
                .withMessage("Negative totals are not allowed.");
    }

    @Test
    public void unsortedAndDuplicateCoins() {
        assertThat(new ChangeCalculator(asList(100, 25, 10, 5, 1)).computeMostEfficientChange(30))
                .containsExactly(5, 25);
        assertThat(new ChangeCalculator(asList(25, 1, 10, 10, 1, 5)).computeMostEfficientChange(15))
                .containsExactly(5, 10);
        assertThat(new ChangeCalculator(asList(3, 7)).computeMostEfficientChange(10))
                .containsExactly(3, 7);
    }
}
